import json, random, subprocess
random.seed(20260929)
OLD=["python3","/tmp/orig_relay.py"]; NEW=["python3","/home/c/brix2/b/task072/relay.py"]

def topo(rng):
    V=rng.randint(3,5)
    names=[chr(65+i) for i in range(V)]
    links=[]
    for a in names:
        for b in names:
            if a!=b and rng.random()<0.55:
                links.append({"from":a,"to":b,"cost":rng.randint(1,4),"up":rng.random()<0.85,
                              "bandwidth":rng.randint(4,12),"latency":rng.randint(0,4)})
    return {"nodes":names,"links":links}

def up_paths(topo):
    adj={n:[] for n in topo["nodes"]}
    for l in topo["links"]:
        if l["up"]: adj[l["from"]].append(l["to"])
    return adj

def simple_path(adj,s,d,rng):
    path=[s]; seen={s}
    def dfs():
        cur=path[-1]
        if cur==d: return True
        nxt=list(adj.get(cur,[])); rng.shuffle(nxt)
        for w in nxt:
            if w not in seen:
                seen.add(w); path.append(w)
                if dfs(): return True
                path.pop(); seen.discard(w)
        return False
    return list(path) if dfs() else None

mism=0; checked=0
for it in range(1500):
    rng=random.Random(it*7+13)
    tp=topo(rng)
    adj=up_paths(tp)
    nodes=tp["nodes"]
    # build a few flows
    flows=[]; ids=set()
    for fi in range(rng.randint(0,4)):
        s,d=rng.sample(nodes,2)
        p=simple_path(adj,s,d,rng)
        if p:
            fid="f%d"%fi; ids.add(fid)
            flows.append([fid,s,d,rng.randint(1,6),p])
    # events kinds 0..3
    ev=[]; t=0
    for _ in range(rng.randint(1,6)):
        t+=rng.choice([0,0,1])
        k=rng.randrange(4)
        if k==0 and tp["links"]:
            l=rng.choice(tp["links"]); ev.append([t,0,l["from"],l["to"],rng.randint(1,12)])
        elif k==1:
            if rng.random()<0.5 and ids:
                fid=rng.choice(sorted(ids))
                ex=next(f for f in flows if f[0]==fid)
                ev.append([t,1,fid,ex[1],ex[2],ex[3]])  # idempotent readd
            else:
                s,d=rng.sample(nodes,2)
                nid="g%d"%rng.randint(0,99)
                ev.append([t,1,nid,s,d,rng.randint(1,6)]); ids.add(nid)
        elif k==2 and ids:
            fid=rng.choice(sorted(ids)); ev.append([t,2,fid]); ids.discard(fid)
        elif k==3 and ids:
            fid=rng.choice(sorted(ids)); ev.append([t,3,fid,rng.randint(1,6)])
    if not ev: continue
    net=json.dumps(tp); fl=json.dumps(flows); evs=json.dumps(ev)
    limit=str(rng.randint(0,3))
    po=subprocess.run(OLD+["flowshift","/dev/stdin",limit,fl,evs],input=net,capture_output=True,text=True)
    pn=subprocess.run(NEW+["flowshift","/dev/stdin",limit,fl,evs],input=net,capture_output=True,text=True)
    # For kinds 0-3: added ids are random g##; an id added AND later deleted/re-added
    # can differ (per-instance fix). Restrict to cases where no added id is re-added
    # after deletion AND ... actually added flows' *moved counting* already differs by
    # design. So only compare when there are NO successful added flows surviving into a
    # later reroute. Simplest: compare only when there are no kind-1 g events at all.
    has_g=any(e[1]==1 and e[2].startswith("g") for e in ev)
    checked+=1
    if has_g:
        continue
