            print("MISMATCH",limit); print(net); print(fl); print(evs)
            print("old",po.returncode,po.stdout[:400],po.stderr)
            print("new",pn.returncode,pn.stdout[:400],pn.stderr)
print("checked",checked,"mismatches(no-add cases)",mism)
