import importlib.util, random, json, io, contextlib

def load(path, name):
    spec=importlib.util.spec_from_file_location(name,path)
    m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
old=load("/tmp/orig_relay.py","relay_old"); new=load("/home/c/brix2/b/task072/relay.py","relay_new")

def topo(rng):
    V=rng.randint(3,4); names=[chr(65+i) for i in range(V)]; links=[]
    for a in names:
        for b in names:
            if a!=b and rng.random()<0.4:
                links.append({"from":a,"to":b,"cost":rng.randint(1,4),"up":rng.random()<0.85,
                              "bandwidth":rng.randint(4,10),"latency":rng.randint(0,4)})
    return names,links

def find_path(upadj,s,d,rng,path=None,seen=None):
    if path is None: path,seen=[s],{s}
    if s==d: return list(path)
    ws=list(upadj.get(s,[])); rng.shuffle(ws)
    for w in ws:
        if w not in seen:
            seen.add(w); path.append(w)
            r=find_path(upadj,w,d,rng,path,seen)
            if r: return r
            path.pop(); seen.discard(w)
    return None

def run(mod,nodes,links,flows,limit,ev):
    buf=io.StringIO()
    try:
        with contextlib.redirect_stderr(buf):
            return ("ok",mod.compute_flowshift(nodes,[dict(l) for l in links],
                    [tuple(f) for f in flows],limit,list(ev)))
    except SystemExit as e:
        return ("fail",e.code)

n=nog=moved_only=real_mm=0
real_examples=[]
for it in range(40000):
    rng=random.Random(it*101+7)
    nodes,links=topo(rng)
    upadj={x:[] for x in nodes}
    for l in links:
        if l["up"]: upadj[l["from"]].append(l["to"])
    flows=[]
    for fi in range(rng.randint(0,3)):
        s,d=rng.sample(nodes,2); p=find_path(upadj,s,d,rng)
        if p: flows.append(("f%d"%fi,s,d,rng.randint(1,5),p))
    ev=[]; t=0; added_ids=set(); initial={f[0] for f in flows}
    for _ in range(rng.randint(1,4)):
        t+=rng.choice([0,0,1]); k=rng.randrange(4)
        if k==0 and links:
            l=rng.choice(links); ev.append((0,t,l["from"],l["to"],rng.randint(1,10)))
        elif k==1:
            if rng.random()<0.45 and flows:
                f=rng.choice(flows)
                ev.append((1,t,f[0],f[1],f[2],f[3]))
            else:
                s,d=rng.sample(nodes,2); nid="g%d"%rng.randint(0,9)
                ev.append((1,t,nid,s,d,rng.randint(1,5))); added_ids.add(nid)
        elif k==2:
            allids={f[0] for f in flows}|added_ids
            if allids:
                fid=rng.choice(sorted(allids)); ev.append((2,t,fid))
        elif k==3 and flows:
            f=rng.choice(flows); ev.append((3,t,f[0],rng.randint(1,5)))
    if not ev: continue
    limit=rng.randint(0,2)
    ro=run(old,nodes,links,flows,limit,ev); rn=run(new,nodes,links,flows,limit,ev)
    if not added_ids: nog+=1
    n+=1
    if ro==rn: continue
    # classify: failures must match; on success only moved counters may differ
    if ro[0]!=rn[0]:
        real_mm+=1; real_examples.append(("kind",ev,ro,rn)); continue
    if ro[0]=="fail":
        real_mm+=1; real_examples.append(("fail",ev,ro,rn)); continue
    eo,en=ro[1]["events"],rn[1]["events"]
    bad=False
    if len(eo)!=len(en): bad=True
    else:
        for a,b in zip(eo,en):
            if [a[0],a[1],a[2],a[3],a[5]]!=[b[0],b[1],b[2],b[3],b[5]]:
                bad=True  # anything but moved(index4) differs
    if ro[1]["links"]!=rn[1]["links"]: bad=True
    if bad:
        real_mm+=1
        if len(real_examples)<5: real_examples.append(("shape",ev,ro,rn))
    else:
        moved_only+=1
print("total",n,"no-add",nog,"moved-only-diff(expected)",moved_only,"UNEXPECTED",real_mm)
