def fmt(num,den):
    sc=(2*num*1000000+den)//(2*den); return "%d.%06d"%(sc//1000000,sc%1000000)

class Ref:
    def __init__(self,nodes,links,flows,limit):
        self.nodes=nodes; self.links=links; self.limit=limit
        self.cap=[l["bandwidth"] for l in links]
        self.idx={(l["from"],l["to"]):i for i,l in enumerate(links)}
        self.lup=[l["up"] for l in links]
        self.nup={n:True for n in nodes}
        self.live=[[f[0],f[1],f[2],f[3],list(f[4])] for f in flows]
        self.mark=[True]*len(flows)
    def adj(self):
        a={n:[] for n in self.nodes}
        for i,l in enumerate(self.links):
            if self.lup[i] and self.nup[l["from"]] and self.nup[l["to"]]:
                a[l["from"]].append(l["to"])
        return a
    def paths(self,adj,s,d):
        res=[]
        def dfs(cur,p,seen):
            if cur==d: res.append(list(p)); return
            for w in sorted(adj.get(cur,[])):
                if w not in seen:
                    seen.add(w); p.append(w); dfs(w,p,seen); p.pop(); seen.discard(w)
        dfs(s,[s],{s}); return res
    def used_peak(self,used):
        num,den=0,1
        for u,c in zip(used,self.cap):
            if u*den>num*c: num,den=u,c
        return num,den
    def optimize(self,cands,marks,bases):
        # cands: [(s,d,b)]; bases: list(path|None); returns dict or None
        adj=self.adj()
        psets=[self.paths(adj,s,d) for s,d,_ in cands]
        if any(len(p)==0 for p in psets): return None
        best=None
        for combo in itertools.product(*psets):
            used=[0]*len(self.links); limited=0; moved=0; ok=True
            for (s,d,b),p,mark,base in zip(cands,combo,marks,bases):
                for a,c in zip(p,p[1:]):
                    used[self.idx[(a,c)]]+=b
                if base is not None and p!=base:
                    moved+=1
                    if mark: limited+=1
            if limited>self.limit: continue
            for u,c in zip(used,self.cap):
                if u>c: ok=False; break
            if not ok: continue
            num,den=self.used_peak(used)
            key=(num,den,moved,combo)
            if best is None:
                best=(num,den,moved,list(combo),used)
            else:
                bn,bd,bm,bv,_=best
                if (num*bd<bn*den or (num*bd==bn*den and
                    (moved<bm or (moved==bm and list(combo)<bv)))):
                    best=(num,den,moved,list(combo),used)
        return best
    def cur_used(self):
        used=[0]*len(self.links)
        for _,_,_,b,p in self.live:
            for a,c in zip(p,p[1:]): used[self.idx[(a,c)]]+=b
        return used
    def snap(self): return [[a,b,c,d,list(p)] for a,b,c,d,p in self.live]
    def process(self,events):
        out=[]
        for e in events:
            k=e[1]; t=e[0]; pos={f[0]:i for i,f in enumerate(self.live)}
            peak=lambda: self.used_peak(self.cur_used())
            if k==0:
                _,_,u,v,b=e; i=self.idx[(u,v)]
                if b==self.cap[i]:
                    n,d=peak(); out.append([t,k,1,fmt(n,d),0,self.snap()]); continue
                old=self.cap[i]; self.cap[i]=b
                cands=[(f[1],f[2],f[3]) for f in self.live]
                r=self.optimize(cands,list(self.mark),[f[4] for f in self.live])
                if r is None:
                    self.cap[i]=old; n,d=peak(); out.append([t,k,2,fmt(n,d),0,self.snap()])
                else:
                    n,d,_,pv,_=r
                    for j,f in enumerate(self.live): f[4]=pv[j]
                    out.append([t,k,0,fmt(n,d),self.movedof(pv,[f[4] for f in self.live][:0]) ,self.snap()])
            elif k==1:
                _,_,nid,s,d,b=e
                if nid in pos:
                    f=self.live[pos[nid]]
                    assert (f[1],f[2],f[3])==(s,d,b), "expected error5"
                    nn,dd=peak(); out.append([t,k,1,fmt(nn,dd),0,self.snap()]); continue
                cands=[(x[1],x[2],x[3]) for x in self.live]+[(s,d,b)]
                marks=list(self.mark)+[False]; bases=[x[4] for x in self.live]+[None]
                r=self.optimize(cands,marks,bases)
                if r is None:
                    nn,dd=peak(); out.append([t,k,2,fmt(nn,dd),0,self.snap()])
                else:
                    n,d,mv,pv,_=r
                    for j in range(len(self.live)): self.live[j][4]=pv[j]
                    self.live.append([nid,s,d,b,pv[-1]]); self.mark.append(False)
                    out.append([t,k,0,fmt(n,d),mv,self.snap()])
            elif k==2:
                _,_,nid=e
                if nid not in pos:
                    nn,dd=peak(); out.append([t,k,1,fmt(nn,dd),0,self.snap()]); continue
                drop=pos[nid]; surv=self.live[:drop]+self.live[drop+1:]
                sm=self.mark[:drop]+self.mark[drop+1:]
                r=self.optimize([(f[1],f[2],f[3]) for f in surv],sm,[f[4] for f in surv])
                assert r is not None
                n,d,mv,pv,_=r
                for j,f in enumerate(surv): f[4]=pv[j]
                self.live=surv; self.mark=sm
                out.append([t,k,0,fmt(n,d),mv,self.snap()])
            elif k==3:
                _,_,nid,b=e; assert nid in pos, "expected error5"
                f=self.live[pos[nid]]
                if b==f[3]:
                    nn,dd=peak(); out.append([t,k,1,fmt(nn,dd),0,self.snap()]); continue
                old=f[3]; f[3]=b
                r=self.optimize([(x[1],x[2],x[3]) for x in self.live],list(self.mark),[x[4] for x in self.live])
                if r is None:
                    f[3]=old; nn,dd=peak(); out.append([t,k,2,fmt(nn,dd),0,self.snap()])
                else:
                    n,d,mv,pv,_=r
                    for j,x in enumerate(self.live): x[4]=pv[j]
                    out.append([t,k,0,fmt(n,d),mv,self.snap()])
            elif k==4:
                _,_,n,up=e
                if self.nup[n]==up:
                    nn,dd=peak(); out.append([t,k,1,fmt(nn,dd),0,self.snap()]); continue
                old=self.nup[n]; self.nup[n]=up
                r=self.optimize([(x[1],x[2],x[3]) for x in self.live],list(self.mark),[x[4] for x in self.live])
                if r is None:
                    self.nup[n]=old; nn,dd=peak(); out.append([t,k,2,fmt(nn,dd),0,self.snap()])
                else:
                    n_,d,mv,pv,_=r
                    for j,x in enumerate(self.live): x[4]=pv[j]
                    out.append([t,k,0,fmt(n_,d),mv,self.snap()])
            else:
                _,_,u,v,up=e; i=self.idx[(u,v)]
                if self.lup[i]==up:
                    nn,dd=peak(); out.append([t,k,1,fmt(nn,dd),0,self.snap()]); continue
                old=self.lup[i]; self.lup[i]=up
                r=self.optimize([(x[1],x[2],x[3]) for x in self.live],list(self.mark),[x[4] for x in self.live])
                if r is None:
                    self.lup[i]=old; nn,dd=peak(); out.append([t,k,2,fmt(nn,dd),0,self.snap()])
                else:
                    n_,d,mv,pv,_=r
                    for j,x in enumerate(self.live): x[4]=pv[j]
                    out.append([t,k,0,fmt(n_,d),mv,self.snap()])
        used=self.cur_used()
        links=[[l["from"],l["to"],self.cap[i],used[i]] for i,l in enumerate(self.links)]
        return {"events":out,"links":links}
    def movedof(self,pv,dummy):
        # moved for a kind0 commit computed against pre-commit live paths
        return sum(1 for f,p in zip(self.live,pv) if f[4]!=p)
