import itertools

def fmt(num, den):
    sc = (2*num*1000000 + den)//(2*den)
    return "%d.%06d" % (sc//1000000, sc%1000000)

class Error5(Exception):
    pass

class Oracle:
    """Independent brute-force model of the six-kind flowshift spec."""
    def __init__(self, nodes, links, flows, limit):
        self.nodes = nodes
        self.links = links
        self.limit = limit
        self.cap = [l["bandwidth"] for l in links]
        self.idx = {(l["from"], l["to"]): i for i, l in enumerate(links)}
        self.lup = [l["up"] for l in links]
        self.nup = {n: True for n in nodes}
        self.live = [[f[0], f[1], f[2], f[3], list(f[4])] for f in flows]
        self.mark = [True]*len(flows)
        u0 = [0]*len(links)
        for _, _, _, bb, pp in self.live:
            for a, c in zip(pp, pp[1:]):
                u0[self.idx[(a, c)]] += bb
        if any(x > self.cap[i] for i, x in enumerate(u0)):
            raise Error5

    def adjacency(self):
        adj = {n: [] for n in self.nodes}
        for i, l in enumerate(self.links):
            if self.lup[i] and self.nup[l["from"]] and self.nup[l["to"]]:
                adj[l["from"]].append(l["to"])
        return adj

    def all_paths(self, adj, s, d):
        out = []
        def go(cur, p, seen):
            if cur == d:
                out.append(list(p)); return
            for w in sorted(adj.get(cur, [])):
                if w not in seen:
                    seen.add(w); p.append(w)
                    go(w, p, seen); p.pop(); seen.discard(w)
        go(s, [s], {s}); return out

    def peak(self, used):
        pn, pd = 0, 1
        for u, c in zip(used, self.cap):
            if u*pd > pn*c: pn, pd = u, c
        return pn, pd

    def optimize(self, cands, marks, bases):
        adj = self.adjacency()
        psets = [self.all_paths(adj, s, d) for s, d, _ in cands]
        if any(not p for p in psets):
            return None
        best = None
        for combo in itertools.product(*psets):
            used = [0]*len(self.links); limited = moved = 0
            for (s, d, bb), pp, mk, base in zip(cands, combo, marks, bases):
                for a, c in zip(pp, pp[1:]):
                    used[self.idx[(a, c)]] += bb
                if base is not None and pp != base:
                    moved += 1
                    if mk: limited += 1
            if limited > self.limit: continue
            if any(used[i] > self.cap[i] for i in range(len(self.links))):
                continue
            pn, pd = self.peak(used)
            if best is None:
                best = (pn, pd, moved, list(combo), used)
            else:
                bn, bd, bm, bv, _ = best
                if (pn*bd < bn*pd or
                    (pn*bd == bn*pd and (moved < bm or
                                         (moved == bm and list(combo) < bv)))):
                    best = (pn, pd, moved, list(combo), used)
        return best

    def cur_used(self):
        used = [0]*len(self.links)
        for _, _, _, bb, pp in self.live:
            for a, c in zip(pp, pp[1:]):
                used[self.idx[(a, c)]] += bb
        return used

    def snap(self):
        return [[a, b, c, bb, list(pp)] for a, b, c, bb, pp in self.live]

    def process(self, events):
        out = []
        for e in events:
            k, t = e[0], e[1]
            pos = {f[0]: i for i, f in enumerate(self.live)}
            def row(status, mv):
                pn, pd = self.peak(self.cur_used())
                return [t, k, status, fmt(pn, pd), mv, self.snap()]
            if k == 0:
                _, _, u, v, nb = e; i = self.idx[(u, v)]
                if nb == self.cap[i]:
                    out.append(row(1, 0)); continue
                old = self.cap[i]; self.cap[i] = nb
                r = self.optimize([(f[1], f[2], f[3]) for f in self.live],
                                  list(self.mark), [f[4] for f in self.live])
                if r is None:
                    self.cap[i] = old; out.append(row(2, 0))
                else:
                    pn, pd, mv, pv, _ = r
                    for j, f in enumerate(self.live): f[4] = pv[j]
                    out.append([t, k, 0, fmt(pn, pd), mv, self.snap()])
            elif k == 1:
                _, _, nid, s, d, bb = e
                if nid in pos:
                    f = self.live[pos[nid]]
                    if (f[1], f[2], f[3]) != (s, d, bb):
                        raise Error5
                    out.append(row(1, 0)); continue
                cands = [(x[1], x[2], x[3]) for x in self.live] + [(s, d, bb)]
                r = self.optimize(cands, list(self.mark) + [False],
                                  [x[4] for x in self.live] + [None])
                if r is None:
                    out.append(row(2, 0))
                else:
                    pn, pd, mv, pv, _ = r
                    for j in range(len(self.live)): self.live[j][4] = pv[j]
                    self.live.append([nid, s, d, bb, pv[-1]]); self.mark.append(False)
                    out.append([t, k, 0, fmt(pn, pd), mv, self.snap()])
            elif k == 2:
                _, _, nid = e
                if nid not in pos:
                    out.append(row(1, 0)); continue
                drop = pos[nid]
                surv = self.live[:drop] + self.live[drop+1:]
                sm = self.mark[:drop] + self.mark[drop+1:]
                r = self.optimize([(f[1], f[2], f[3]) for f in surv], sm,
                                  [f[4] for f in surv])
                if r is None:
                    out.append(row(2, 0))
                else:
                    pn, pd, mv, pv, _ = r
                    for j, f in enumerate(surv): f[4] = pv[j]
                    self.live = surv; self.mark = sm
                    out.append([t, k, 0, fmt(pn, pd), mv, self.snap()])
            elif k == 3:
                _, _, nid, nb = e
                if nid not in pos:
                    raise Error5
                f = self.live[pos[nid]]
                if nb == f[3]:
                    out.append(row(1, 0)); continue
                old = f[3]; f[3] = nb
                r = self.optimize([(x[1], x[2], x[3]) for x in self.live],
                                  list(self.mark), [x[4] for x in self.live])
                if r is None:
                    f[3] = old; out.append(row(2, 0))
                else:
                    pn, pd, mv, pv, _ = r
                    for j, x in enumerate(self.live): x[4] = pv[j]
                    out.append([t, k, 0, fmt(pn, pd), mv, self.snap()])
            elif k == 4:
                _, _, n, up = e
                if self.nup[n] == up:
                    out.append(row(1, 0)); continue
                old = self.nup[n]; self.nup[n] = up
                r = self.optimize([(x[1], x[2], x[3]) for x in self.live],
                                  list(self.mark), [x[4] for x in self.live])
                if r is None:
                    self.nup[n] = old; out.append(row(2, 0))
                else:
                    pn, pd, mv, pv, _ = r
                    for j, x in enumerate(self.live): x[4] = pv[j]
                    out.append([t, k, 0, fmt(pn, pd), mv, self.snap()])
            else:
                _, _, u, v, up = e; i = self.idx[(u, v)]
                if self.lup[i] == up:
                    out.append(row(1, 0)); continue
                old = self.lup[i]; self.lup[i] = up
                r = self.optimize([(x[1], x[2], x[3]) for x in self.live],
                                  list(self.mark), [x[4] for x in self.live])
                if r is None:
                    self.lup[i] = old; out.append(row(2, 0))
                else:
                    pn, pd, mv, pv, _ = r
                    for j, x in enumerate(self.live): x[4] = pv[j]
                    out.append([t, k, 0, fmt(pn, pd), mv, self.snap()])
        return {"events": out,
                "links": [[l["from"], l["to"], self.cap[i], self.cur_used()[i]]
                          for i, l in enumerate(self.links)]}
